tw.local.userConditions = new tw.object.userConditions();
var arr=[];
arr = tw.local.data.split('_');

tw.local.userConditions.requestNature = arr[0];
tw.local.userConditions.role = arr[1];

if(tw.local.userConditions.requestNature ==null)
log.info("ODC Service Get request type >>>request nature is empty ");

if(tw.local.userConditions.role ==null)
log.info("ODC Service Get request type >>>role is empty ");

log.info("=========================================TEST dataaaaaaa==================="+tw.local.data);
log.info("array"+arr);
log.info("role==="+tw.local.userConditions.role);
log.info("request nature==="+tw.local.userConditions.requestNature);

tw.local.results    =  new tw.object.listOf.NameValuePair();
tw.local.conditions =  new tw.object.listOf.NameValuePair();

if(tw.local.userConditions.requestNature.toLowerCase() == "new")
{
	tw.local.conditions[0] = new tw.object.NameValuePair();
	tw.local.conditions[0].name = "ODC Create";
	tw.local.conditions[0].value = "" + tw.epv.RequestType.Create;
	log.info("requset new");
}
else if(tw.local.userConditions.requestNature.toLowerCase() == "update")
{
	
	if(tw.local.userConditions.role.toLowerCase() == "hub")
	{
		tw.local.conditions[0] = new tw.object.NameValuePair();
		tw.local.conditions[0].name = "ODC Amendment";
		tw.local.conditions[0].value = "" + tw.epv.RequestType.Amendment; 
		
		tw.local.conditions[1] = new tw.object.NameValuePair();
		tw.local.conditions[1].name = "ODC Re-create";
		tw.local.conditions[1].value = "" + tw.epv.RequestType.Recreate; 
		
		tw.local.conditions[2] = new tw.object.NameValuePair();
		tw.local.conditions[2].name = "ODC Closure";
		tw.local.conditions[2].value = "" + tw.epv.RequestType.Closure;
		
		tw.local.conditions[3] = new tw.object.NameValuePair();
		tw.local.conditions[3].name = "ODC Collection";
		tw.local.conditions[3].value = "" + tw.epv.RequestType.Collection;
		
		tw.local.conditions[4] = new tw.object.NameValuePair();
		tw.local.conditions[4].name = "ODC Reversal";
		tw.local.conditions[4].value = ""+tw.epv.RequestType.Reversal;
	}
	else
	{
		tw.local.conditions[0] = new tw.object.NameValuePair();
		tw.local.conditions[0].name = "ODC Amendment";
		tw.local.conditions[0].value = "" + tw.epv.RequestType.Amendment
		
		tw.local.conditions[1] = new tw.object.NameValuePair();
		tw.local.conditions[1].name = "ODC Re-create";
		tw.local.conditions[1].value ="" + tw.epv.RequestType.Recreate;
		
		tw.local.conditions[2] = new tw.object.NameValuePair();
		tw.local.conditions[2].name = "ODC Closure";
		tw.local.conditions[2].value ="" + tw.epv.RequestType.Closure;  
	}
}

tw.local.results = tw.local.conditions;

